UPDATE user_stats
SET published_article_count = GREATEST(published_article_count + #{delta}, 0)
WHERE user_id = #{userId}

UPDATE user_stats
SET moe_point = moe_point - #{amount}
WHERE user_id = #{userId} AND moe_point >= #{amount}

UPDATE user_stats
SET moe_point = moe_point + #{amount}
WHERE user_id = #{userId}

UPDATE user_stats
SET follow_count = GREATEST(follow_count + #{delta}, 0)
WHERE user_id = #{userId}

UPDATE user_stats
SET fan_count = GREATEST(fan_count + #{delta}, 0)
WHERE user_id = #{userId}
